// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 t1, uint256 t2, address actor) public {
        t1 = bound(t1, 1, 1e12);
        t2 = bound(t2, t1, 1e12); // t2 may equal t1 (same timestamp)
        vm.assume(actor != address(c) && actor != address(this));

        // first call at t1
        vm.warp(t1);
        vm.deal(actor, 20 ether);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        // second call at t2; if t2 == t1 the guard must reject it
        vm.warp(t2);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        // General rule: with t2 >= t1, the second call is accepted only if
        // t2 is strictly greater than the previously accepted timestamp.
        assertTrue(!ok2 || t2 > t1);
    }
}
